<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php'; require_admin();
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if($action==='create'){
   $y=trim($_POST['academic_year']??'');$t=trim($_POST['term']??'');$e=trim($_POST['exam_type']??'');
   if(!preg_match('/^\d{4}\/\d{4}$/',$y)||!$t||!$e)throw new RuntimeException('Enter a valid academic year, term and examination.');
   period_ensure($dbh,$y,$t,$e);$msg='Academic period created.';audit_log($dbh,'PERIOD_CREATE',$y.' / '.$t.' / '.$e);
  } elseif($action==='activate'){
   $dbh->beginTransaction();$q=$dbh->prepare('SELECT academic_year,term,exam_type,is_locked FROM academic_periods WHERE id=:id');$q->execute([':id'=>$id]);$p=$q->fetch();if(!$p)throw new RuntimeException('Period not found.');if($p['is_locked'])throw new RuntimeException('A locked period cannot be activated.');
   $dbh->exec('UPDATE academic_periods SET is_active=0');$u=$dbh->prepare('UPDATE academic_periods SET is_active=1,updated_at=NOW() WHERE id=:id');$u->execute([':id'=>$id]);$dbh->commit();$msg='Academic period activated.';audit_log($dbh,'PERIOD_ACTIVATE',$p['academic_year'].' / '.$p['term'].' / '.$p['exam_type']);
  } elseif($action==='lock' || $action==='unlock'){
   $q=$dbh->prepare('SELECT * FROM academic_periods WHERE id=:id');$q->execute([':id'=>$id]);$p=$q->fetch();if(!$p)throw new RuntimeException('Period not found.');
   if($action==='lock'){$u=$dbh->prepare('UPDATE academic_periods SET is_locked=1,locked_at=NOW(),locked_by=:a,updated_at=NOW() WHERE id=:id');$u->execute([':a'=>$_SESSION['admin_id'],':id'=>$id]);$msg='Period locked. Results in this period are now read-only.';audit_log($dbh,'PERIOD_LOCK',$p['academic_year'].' / '.$p['term'].' / '.$p['exam_type']);}
   else{$u=$dbh->prepare('UPDATE academic_periods SET is_locked=0,locked_at=NULL,locked_by=NULL,updated_at=NOW() WHERE id=:id');$u->execute([':id'=>$id]);$msg='Period unlocked.';audit_log($dbh,'PERIOD_UNLOCK',$p['academic_year'].' / '.$p['term'].' / '.$p['exam_type']);}
  } elseif($action==='delete'){
   $q=$dbh->prepare('SELECT * FROM academic_periods WHERE id=:id');$q->execute([':id'=>$id]);$p=$q->fetch();if(!$p)throw new RuntimeException('Period not found.');$c=$dbh->prepare('SELECT COUNT(*) FROM tblresult WHERE AcademicYear=:y AND Term=:t AND ExamType=:e');$c->execute([':y'=>$p['academic_year'],':t'=>$p['term'],':e'=>$p['exam_type']]);if($c->fetchColumn()>0)throw new RuntimeException('This period has results and cannot be deleted.');$dbh->prepare('DELETE FROM academic_periods WHERE id=:id')->execute([':id'=>$id]);$msg='Period deleted.';
  }
 }catch(Throwable $x){if($dbh->inTransaction())$dbh->rollBack();$error=$x->getMessage();}
}
$rows=$dbh->query('SELECT p.*,a.username AS locker FROM academic_periods p LEFT JOIN admin a ON a.id=p.locked_by ORDER BY p.is_active DESC,p.academic_year DESC,p.id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academic Periods | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><div class="srms-toolbar"><a href="dashboard.php" class="btn btn-default">← Dashboard</a><a href="manage-results.php" class="btn btn-primary">Results</a><a href="result-history.php" class="btn btn-info">History</a></div><h2>Academic Years &amp; Terms</h2><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading"><strong>Create Academic Period</strong></div><div class="panel-body"><form method="post" class="row"><?php echo csrf_field();?><input type="hidden" name="action" value="create"><div class="col-sm-3"><label>Academic Year</label><input name="academic_year" class="form-control" placeholder="2026/2027" required></div><div class="col-sm-3"><label>Term</label><select name="term" class="form-control"><option>Term 1</option><option>Term 2</option><option>Term 3</option><option>Final</option></select></div><div class="col-sm-4"><label>Examination</label><input name="exam_type" class="form-control" placeholder="Final Examination" required></div><div class="col-sm-2" style="padding-top:25px"><button class="btn btn-primary">Create</button></div></form></div></div><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Year</th><th>Term</th><th>Examination</th><th>Active</th><th>Lock</th><th>Locked By</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['academic_year']);?></td><td><?php echo e($r['term']);?></td><td><?php echo e($r['exam_type']);?></td><td><?php echo $r['is_active']?'<span class="label label-success">Active</span>':'<span class="label label-default">Inactive</span>';?></td><td><?php echo $r['is_locked']?'<span class="label label-danger">Locked</span>':'<span class="label label-success">Open</span>';?></td><td><?php echo e($r['locker']??'—');?></td><td><?php if(!$r['is_active']&&!$r['is_locked']):?><form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="activate"><input type="hidden" name="id" value="<?php echo $r['id'];?>"><button class="btn btn-primary btn-xs">Activate</button></form><?php endif;?> <?php if(!$r['is_locked']):?><form method="post" style="display:inline" onsubmit="return confirm('Lock this academic period? Results will become read-only.');"><?php echo csrf_field();?><input type="hidden" name="action" value="lock"><input type="hidden" name="id" value="<?php echo $r['id'];?>"><button class="btn btn-warning btn-xs">Lock Results</button></form><?php else:?><form method="post" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="action" value="unlock"><input type="hidden" name="id" value="<?php echo $r['id'];?>"><button class="btn btn-default btn-xs">Unlock</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
